// ── mocks ────────────────────────────────────────────────────────────────────

struct MockResolver {
    // step name -> (node id, intent); interior mutability lets tests simulate
    // upstream state changes (tampering) between approve and dispatch.
    inner: std::sync::RwLock<HashMap<String, (Uuid, ExecutionIntent)>>,
}

impl MockResolver {
    fn from(intents: Vec<(&str, ExecutionIntent)>) -> Self {
        let mut by_name = HashMap::new();
        for (name, intent) in intents {
            by_name.insert(name.to_string(), (Uuid::new_v4(), intent));
        }
        Self {
            inner: std::sync::RwLock::new(by_name),
        }
    }

    /// Resolver with caller-controlled node ids — a resumed process must keep
    /// the SAME node ids as the pausing process (persisted graph identity).
    fn from_fixed(nodes: Vec<(Uuid, &str, ExecutionIntent)>) -> Self {
        let mut by_name = HashMap::new();
        for (id, name, intent) in nodes {
            by_name.insert(name.to_string(), (id, intent));
        }
        Self {
            inner: std::sync::RwLock::new(by_name),
        }
    }

    fn tamper(&self, name: &str, intent: ExecutionIntent) {
        if let Some(entry) = self.inner.write().unwrap().get_mut(name) {
            entry.1 = intent;
        }
    }
}

#[async_trait::async_trait]
impl NodeIntentResolver for MockResolver {
    async fn resolve_by_step_name(&self, step_name: &str) -> Option<ResolvedNode> {
        let map = self.inner.read().unwrap();
        map.get(step_name).map(|(id, intent)| ResolvedNode {
            node_id: *id,
            step_name: step_name.to_string(),
            intent: intent.clone(),
        })
    }
    async fn resolve_by_node_id(&self, node_id: Uuid) -> Option<ResolvedNode> {
        let map = self.inner.read().unwrap();
        map.iter()
            .find(|(_, (id, _))| *id == node_id)
            .map(|(name, (id, intent))| ResolvedNode {
                node_id: *id,
                step_name: name.clone(),
                intent: intent.clone(),
            })
    }
}

fn run_command(command: &str) -> ExecutionIntent {
    ExecutionIntent {
        tool: "run_command".into(),
        intent: json!({"command": command}),
        declared_scope: vec![],
    }
}

fn service(
    resolver: Arc<MockResolver>,
    repo: Arc<dyn ApprovalRepository>,
    ttl: Duration,
) -> ApprovalServiceImpl {
    ApprovalServiceImpl::new(repo, resolver, b"run-key".to_vec(), ttl)
}

fn approve_input(dag: Uuid, step: &str, approver: &str) -> ApproveInput {
    ApproveInput {
        dag_id: dag,
        step_names: vec![step.to_string()],
        approver_id: approver.to_string(),
        authority: Some("role:operator".into()),
        decision_context: None,
        token_claims_ref: Some("tok-ref".into()),
    }
}

